head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > getCheckedValues]<br/>CheckBox 가 선택 상태인 트리 아이템의 Value 값을 배열로 반환합니다.",
    "validation" : [
        "options(선택) 파라미터로 CheckBox 가 선택된 트리 아이템 중 반환되는 트리 아이템의 조건을 추가 설정합니다.",
        "hierarchy(선택) 조건으로 hierarchy 속성에 의해 반투명 체크 이미지가 표시된 부모 아이템의 포함 여부를 true/false 로 설정합니다.",
        "hierarchy(선택) 조건으로 true 설정 시 반환값에 반투명 체크 이미지가 표시된 부모 아이템을 포함합니다.",
        "hierarchy(선택) 조건으로 미설정 또는 false 설정 시 반환값에 반투명 체크 이미지가 표시된 부모 아이템을 포함합니다.",
        "반환값으로 CheckBox 가 선택된 트리 아이템 중 파라미터 조건을 만족하는 트리 아이템의 Value 값을 배열로 반환합니다.",
        "반환값은 Breadth-First Search 방식으로 검색됩니다.",        
        "CheckBox 가 선택된 트리 아이템이 없는 경우 빈 배열을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {            
        showCheckbox : true,            
        hierarchy : true,
    }

    let cList = $c.gcm.createCList(properties);  
    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createBasicTreeView(cList, eList);
}



scwin.btn_getCheckedValues_onclick = function (e) {   
    let rtn = '';
    let options = par_options.getText();

    if (options == "")
        rtn = target1.getCheckedValues();
    else 
        rtn = target1.getCheckedValues({hierarchy:true});

    wf_body_bottom.getObj("scwin").setReturnValue("getCheckedValues : "+ rtn)
};



scwin.target1_onclick = function (e) {
    scwin.btn_getCheckedValues_onclick();
}
